-- Carga de dados inicial

BEGIN;

DO $$
BEGIN
    IF (SELECT count(*) FROM billing.customers) > 0 THEN
        RAISE EXCEPTION 'O schema "billing" já possui dados. Execute em uma base limpa.';
    END IF;
END $$;

